169→/// Execute a command with streaming output.
170→pub fn execute_streaming(
171→    command: &str,
172→    options: &CommandOptions,
173→    callback: OutputCallback,
174→) -> Result<CommandResult> {
175→    let start = Instant::now();
176→
177→    let shell = detect_shell();
178→    let shell_flag = shell_flag(&shell);
179→
180→    let mut cmd = Command::new(&shell);
181→    cmd.arg(shell_flag);
182→    cmd.arg(command);
183→
184→    if let Some(cwd) = &options.cwd {
185→        cmd.current_dir(cwd);
186→    }
187→
188→    for (key, value) in &options.env {
189→        cmd.env(key, value);
190→    }
191→
192→    cmd.stdout(Stdio::piped());
193→    cmd.stderr(Stdio::piped());
194→
195→    let mut child = cmd.spawn().map_err(|_| BivvyError::CommandFailed {
196→        command: command.to_string(),
197→        code: None,
198→    })?;
199→
200→    let stdout = child.stdout.take().unwrap();
201→    let stderr = child.stderr.take().unwrap();
202→
203→    let (tx, rx) = mpsc::channel();
204→    let tx_stdout = tx.clone();
205→    let tx_stderr = tx;
206→
207→    // Spawn threads to read stdout and stderr
208→    let stdout_handle = thread::spawn(move || {
209→        let reader = BufReader::new(stdout);
210→        let mut output = String::new();
211→        for line in reader.lines().map_while(std::result::Result::ok) {
212→            output.push_str(&line);
213→            output.push('\n');
214→            let _ = tx_stdout.send(OutputLine::Stdout(line));
215→        }
216→        output
217→    });
218→
219→    let stderr_handle = thread::spawn(move || {
220→        let reader = BufReader::new(stderr);
221→        let mut output = String::new();
222→        for line in reader.lines().map_while(std::result::Result::ok) {
223→            output.push_str(&line);
224→            output.push('\n');
225→            let _ = tx_stderr.send(OutputLine::Stderr(line));
226→        }
227→        output
228→    });
229→
230→    // Process output through callback
231→    for line in rx {
232→        callback(line);
233→    }
234→
235→    let stdout_output = stdout_handle.join().unwrap_or_default();
236→    let stderr_output = stderr_handle.join().unwrap_or_default();
237→
238→    let status = child.wait().map_err(|_| BivvyError::CommandFailed {
239→        command: command.to_string(),
240→        code: None,
241→    })?;
242→
243→    let duration = start.elapsed();
244→
245→    if status.success() {
246→        Ok(CommandResult::success(
247→            stdout_output,
248→            stderr_output,
249→            duration,

250→        ))
251→    } else {
252→        Ok(CommandResult::failure(
253→            status.code(),
254→            stdout_output,
255→            stderr_output,
256→            duration,
257→        ))
258→    }
259→}
