app_name: EnvTest
settings:
  environments:
    staging:
      detect:
        - env: BIVVY_TEST_STAGING
          value: "1"
      default_workflow: staging
      provided_requirements:
        - postgres-server
steps:
  always:
    command: echo always
  ci_only:
