  1→//! Resolved step ready for execution.
  2→//!
  3→//! A ResolvedStep combines template defaults with config overrides,
  4→//! producing a fully-specified step that can be executed.
  5→
  6→use crate::config::schema::StepEnvironmentOverride;
  7→use crate::config::{CompletedCheck, StepConfig};
  8→use crate::registry::template::Template;
  9→use std::collections::HashMap;
 10→
 11→/// A fully resolved step ready for execution.
 12→#[derive(Debug, Clone)]
 13→pub struct ResolvedStep {
 14→    /// Step name (key from config).
 15→    pub name: String,
 16→
 17→    /// Display title.
 18→    pub title: String,
 19→
 20→    /// Description.
 21→    pub description: Option<String>,
 22→
 23→    /// Command to execute.
 24→    pub command: String,
 25→
 26→    /// Dependencies.
 27→    pub depends_on: Vec<String>,
 28→
 29→    /// Completion check.
 30→    pub completed_check: Option<CompletedCheck>,
 31→
 32→    /// Precondition that must pass before running.
 33→    pub precondition: Option<CompletedCheck>,
 34→
 35→    /// Whether step can be skipped.
 36→    pub skippable: bool,
 37→
 38→    /// Whether step is required.
 39→    pub required: bool,
 40→
 41→    /// Prompt before re-running completed.
 42→    pub prompt_if_complete: bool,
 43→
 44→    /// Continue on failure.
 45→    pub allow_failure: bool,
 46→
 47→    /// Retry count.
 48→    pub retry: u32,
 49→
 50→    /// Environment variables.
 51→    pub env: HashMap<String, String>,
 52→
 53→    /// Files to watch.
 54→    pub watches: Vec<String>,
 55→
 56→    /// Before hooks.
 57→    pub before: Vec<String>,
 58→
 59→    /// After hooks.
 60→    pub after: Vec<String>,
 61→
 62→    /// Sensitive step.
 63→    pub sensitive: bool,
 64→
 65→    /// Requires sudo.
 66→    pub requires_sudo: bool,
 67→
 68→    /// System-level prerequisites this step requires.
 69→    pub requires: Vec<String>,
 70→
 71→    /// Restrict this step to specific environments.
 72→    /// Empty means "run in all environments".
 73→    pub only_environments: Vec<String>,
 74→}
 75→
 76→impl ResolvedStep {
 77→    /// Create from a step config that uses a template.
 78→    ///
 79→    /// When `environment` is `Some`, applies matching per-environment overrides
 80→    /// from the step config after the base resolution.
 81→    pub fn from_template(
 82→        name: &str,
 83→        template: &Template,
 84→        config: &StepConfig,
 85→        _inputs: &HashMap<String, serde_yaml::Value>,
 86→        environment: Option<&str>,
 87→    ) -> Self {
 88→        let step = &template.step;
 89→
 90→        let mut resolved = Self {
 91→            name: name.to_string(),
 92→            title: config
 93→                .title
 94→                .clone()
 95→                .or_else(|| step.title.clone())
 96→                .unwrap_or_else(|| name.to_string()),
 97→            description: config
 98→                .description
 99→                .clone()
100→                .or_else(|| step.description.clone()),
101→            command: config
102→                .command
103→                .clone()
104→                .or_else(|| step.command.clone())
105→                .unwrap_or_default(),
106→            depends_on: config.depends_on.clone(),
107→            completed_check: config
108→                .completed_check
109→                .clone()
110→                .or_else(|| step.completed_check.clone()),
111→            precondition: config.precondition.clone(),
112→            skippable: config.skippable,
113→            required: config.required,
114→            prompt_if_complete: config.prompt_if_complete,
115→            allow_failure: config.allow_failure,
116→            retry: config.retry,
117→            env: merge_env(&step.env, &config.env),
118→            watches: if config.watches.is_empty() {
119→                step.watches.clone()
120→            } else {
121→                config.watches.clone()
122→            },
123→            before: config.before.clone(),
124→            after: config.after.clone(),
125→            sensitive: config.sensitive,
126→            requires_sudo: config.requires_sudo,
127→            requires: merge_requires(&step.requires, &config.requires),
128→            only_environments: config.only_environments.clone(),
129→        };
130→
131→        if let Some(env_name) = environment {
132→            if let Some(overrides) = config.environments.get(env_name) {
133→                resolved.apply_environment_overrides(overrides);
134→            }
135→        }
136→
137→        resolved
138→    }
139→
140→    /// Create from an inline step config (no template).
141→    ///
142→    /// When `environment` is `Some`, applies matching per-environment overrides
143→    /// from the step config after the base resolution.
144→    pub fn from_config(name: &str, config: &StepConfig, environment: Option<&str>) -> Self {
145→        let mut resolved = Self {
146→            name: name.to_string(),
147→            title: config.title.clone().unwrap_or_else(|| name.to_string()),
148→            description: config.description.clone(),
149→            command: config.command.clone().unwrap_or_default(),
150→            depends_on: config.depends_on.clone(),
151→            completed_check: config.completed_check.clone(),
152→            precondition: config.precondition.clone(),
153→            skippable: config.skippable,
154→            required: config.required,
155→            prompt_if_complete: config.prompt_if_complete,
156→            allow_failure: config.allow_failure,
157→            retry: config.retry,
158→            env: config.env.clone(),
159→            watches: config.watches.clone(),
160→            before: config.before.clone(),
161→            after: config.after.clone(),
162→            sensitive: config.sensitive,
163→            requires_sudo: config.requires_sudo,
164→            requires: config.requires.clone(),
165→            only_environments: config.only_environments.clone(),
166→        };
167→
168→        if let Some(env_name) = environment {
169→            if let Some(overrides) = config.environments.get(env_name) {
170→                resolved.apply_environment_overrides(overrides);
171→            }
172→        }
173→
174→        resolved
175→    }
176→
177→    /// Apply per-environment overrides to this resolved step.
178→    ///
179→    /// Only fields that are `Some` in the override will replace the base values.
180→    /// The `env` field supports add/override (`Some(val)`) and removal (`None`).
181→    pub fn apply_environment_overrides(&mut self, overrides: &StepEnvironmentOverride) {
182→        if let Some(t) = &overrides.title {
183→            self.title = t.clone();
184→        }
185→        if let Some(d) = &overrides.description {
186→            self.description = Some(d.clone());
187→        }
188→        if let Some(cmd) = &overrides.command {
189→            self.command = cmd.clone();
190→        }
191→        for (k, v) in &overrides.env {
192→            match v {
193→                Some(val) => {
194→                    self.env.insert(k.clone(), val.clone());
195→                }
196→                None => {
197→                    self.env.remove(k);
198→                }
199→            }
200→        }
201→        if let Some(check) = &overrides.completed_check {
202→            self.completed_check = Some(check.clone());
203→        }
204→        if let Some(check) = &overrides.precondition {
205→            self.precondition = Some(check.clone());
206→        }
207→        if let Some(v) = overrides.skippable {
208→            self.skippable = v;
209→        }
210→        if let Some(v) = overrides.allow_failure {
211→            self.allow_failure = v;
212→        }
213→        if let Some(v) = overrides.requires_sudo {
214→            self.requires_sudo = v;
215→        }
216→        if let Some(v) = overrides.sensitive {
217→            self.sensitive = v;
218→        }
219→        if let Some(hooks) = &overrides.before {
220→            self.before = hooks.clone();
221→        }
222→        if let Some(hooks) = &overrides.after {
223→            self.after = hooks.clone();
224→        }
225→        if let Some(deps) = &overrides.depends_on {
226→            self.depends_on = deps.clone();
227→        }
228→        if let Some(reqs) = &overrides.requires {
229→            self.requires = reqs.clone();
230→        }
231→        if let Some(w) = &overrides.watches {
232→            self.watches = w.clone();
233→        }
234→        if let Some(r) = overrides.retry {
235→            self.retry = r;
236→        }
237→    }
238→}
