240→fn merge_requires(template_requires: &[String], config_requires: &[String]) -> Vec<String> {
241→    let mut seen = std::collections::HashSet::new();
242→    let mut result = Vec::new();
243→    for r in template_requires.iter().chain(config_requires.iter()) {
244→        if seen.insert(r.clone()) {
245→            result.push(r.clone());
246→        }
247→    }
248→    result
249→}
250→
251→fn merge_env(
252→    template_env: &HashMap<String, String>,
253→    config_env: &HashMap<String, String>,
254→) -> HashMap<String, String> {
255→    let mut result = template_env.clone();
256→    result.extend(config_env.iter().map(|(k, v)| (k.clone(), v.clone())));
257→    result
258→}
