if options.dry_run {
    let command = resolve_string(&step.command, context)?;
    let mut lines = Vec::new();

    if step.sensitive {
        lines.push("[SENSITIVE - command hidden in dry-run]".to_string());
    } else {
        lines.push(format!("Would run: {}", command));
    }

    if !step.before.is_empty() {
        for hook in &step.before {
            let resolved_hook = resolve_string(hook, context)?;
            lines.push(format!("  Before: {}", resolved_hook));
        }
    }

    if !step.after.is_empty() {
        for hook in &step.after {
            let resolved_hook = resolve_string(hook, context)?;
            lines.push(format!("  After: {}", resolved_hook));
        }
    }

    if !step.env.is_empty() {
        let mut keys: Vec<_> = step.env.keys().collect();
        keys.sort();
        for key in keys {
            lines.push(format!("  Env: {}={}", key, step.env[key]));
        }
    }

    return Ok(StepResult::success(
        &step.name,
        Duration::ZERO,
        None,
        Some(lines.join("\n")),
    ));
}

